const fs = require('fs');
const path = require('path');
//PARAMETERS FILE WILL ALWAYS BE IN CUCUMBER-CONFIG FOLDER AT ROOT LEVEL
const parametersPath = path.resolve(process.cwd(), 'cucumber-config/parameters');
let parameters = fs.existsSync(parametersPath) ? fs.readFileSync(parametersPath, { encoding: 'utf8' }) : '';
parameters = parameters.toString().split('\n');

let myObj = { portNumber: 5000 };

const getParameters = () => {
    for (const param of parameters) {
        const currentParam = param.split('=');
        if (currentParam.length > 1) {
            const key = currentParam[0].trim().replace(/["]/g, '');
            let value = currentParam[1].trim().replace(/["]/g, '');
            if (key === 'portNumber') {
                if (value === '') {
                    console.log(
                        '"portNumber" parameter is empty. Add a new number or leave it to default number (5000).\n',
                    );
                    process.exit(1);
                } else if (!value.match(/^[0-9]+$/)) {
                    console.log('"portNumber" parameter should only contain numbers.\n');
                    process.exit(1);
                }
            }
            if (key === 'report_folder') {
                const regex = new RegExp(/\\/);
                if (regex.test(value) === true) {
                    value = value.split(/\\/g);
                    value = path.join(...value);
                }
            }
            myObj[key] = value;
        }
    }

    return myObj;
};

const createEnvironmentProperties = () => {
    console.log(`Creating Environment details`);
    const tags = ('CUCUMBER_TAGS' in process.env && process.env.CUCUMBER_TAGS) || ''; //same code as in wdio.js - might be displayed only with npm run cloud-chrome cmd
    const url = process.env.CUCUMBER_BASE_URL || process.env.baseUrl;
    const environmentOutput =
        `browser = Chrome\n` +
        `baseUrl = ${url}\n` +
        `CucumberTAGS  = ${tags}\n` +
        `loginUserName = ${process.env.loginUserName}\n` +
        `loginPassword = ********\n` +
        `loginUserRootName = ${process.env.loginUserRootName}\n` +
        `loginUserRootPassword = ********\n` +
        `loginType = ${process.env.loginType}\n` +
        `endPointRoot = ${process.env.endPointRoot}\n` +
        `endPointName1 = ${process.env.endPointName1}\n` +
        `endPointName2 = ${process.env.endPointName2}\n` +
        `x3SolutionName = ${process.env.x3SolutionName}\n` +
        `downloadFolder = ${process.env.downloadFolder.replace(/\\/g, '\\\\')}\n` +
        `userStoredValuesFile = ${process.env.userStoredValuesFile}\n` +
        `timeout = ${process.env.timeout}\n` +
        `timeoutLocks = ${process.env.timeoutLocks}\n` +
        `timeoutPrints = ${process.env.timeoutPrints}\n` +
        `timeoutWaitfor = ${process.env.timeoutWaitfor}\n` +
        `timeoutCucumber = ${process.env.timeoutCucumber}\n` +
        `browserLanguage = ${process.env.browserLanguage}\n`;

    //create environment file located in the allure-results folder
    const { report_folder } = getParameters();
    const reportFolder = report_folder || 'report';
    const targetFile = path.join(process.cwd(), reportFolder, '/allure-results/environment.properties');
    try {
        fs.writeFileSync(targetFile, environmentOutput, 'utf-8');
    } catch (error) {
        console.log(error);
    }
    console.log('Environment properties file created');
};

const deleteEnvironmentProperties = () => {
    console.log(`Deleting Environment details`);
    delete process.env.CUCUMBER_TAGS;
    delete process.env.CUCUMBER_BASE_URL;
    delete process.env.baseUrl;
    delete process.env.loginUserName;
    delete process.env.loginPassword;
    delete process.env.loginUserRootName;
    delete process.env.loginUserRootPassword;
    delete process.env.loginType;
    delete process.env.endPointRoot;
    delete process.env.endPointName1;
    delete process.env.endPointName2;
    delete process.env.x3SolutionName;
    delete process.env.downloadFolder;
    delete process.env.userStoredValuesFile;
    delete process.env.timeout;
    delete process.env.timeoutLocks;
    delete process.env.timeoutPrints;
    delete process.env.timeoutWaitfor;
    delete process.env.timeoutCucumber;
    delete process.env.browserLanguage;

    //create environment file located in the allure-results folder

    console.log('Environment properties deleted');
};

module.exports = {
    deleteEnvironmentProperties: deleteEnvironmentProperties,
    getParameters: getParameters,
    createEnvironmentProperties: createEnvironmentProperties,
};
